import {
    FloatingFocusManager,
    FloatingNode,
    FloatingOverlay,
    useDismiss,
    useFloating,
    useFloatingNodeId,
    useInteractions,
    useRole,
} from '@floating-ui/react';

import {useForkRef} from '../../../hooks';
import {useFloatingTransition} from '../../../hooks/private/useFloatingTransition';
import type {ModalProps} from '../../Modal';
import {Portal} from '../../Portal';
import {useDefaultProps} from '../../theme/useDefaultProps';
import {block} from '../../utils/cn';
import {filterDOMProps} from '../../utils/filterDOMProps';
import {DRAWER_ANIMATION_DURATION_MS} from '../constants';
import {useInitialFocus} from '../hooks/useInitialFocus';
import type {DrawerPlacement, OnResizeHandler} from '../hooks/useResizeHandlers';
import i18n from '../i18n';

import {DrawerItem} from './DrawerItem';

import './Drawer.scss';

const b = block('drawer');

export interface DrawerProps
    extends Omit<
        ModalProps,
        | 'disableHeightTransition'
        | 'onClose'
        | 'onEscapeKeyDown'
        | 'onEnterKeyDown'
        | 'onOutsideClick'
    > {
    /**
     * Specifies the side from which the drawer should slide in, `left` by default.
     * @default left
     */
    placement?: DrawerPlacement;
    /**
     * Enables resizing of the drawer via pointer.
     * @default false
     */
    resizable?: boolean;
    /**
     * Width or size of the drawer in pixels.
     * When the 'auto' option is passed, the Drawer's width or height will adjust to fit its content.
     */
    size?: number | 'auto';
    /**
     * Min width of the drawer in pixels.
     */
    minSize?: number;
    /**
     * Max width of the drawer in pixels.
     */
    maxSize?: number;
    /**
     * Callback called at the start of resizing.
     */
    onResizeStart?: OnResizeHandler;
    /**
     * Callback called when the drawer is being resized.
     */
    onResize?: OnResizeHandler;
    /**
     * Callback called at the end of resizing.
     */
    onResizeEnd?: OnResizeHandler;
    /**
     * Removes the drawer's veil.
     * @default false
     */
    hideVeil?: boolean;
    /**
     * Disables the drawer's animation.
     * @default false
     */
    disableTransition?: boolean;
}

export const Drawer = (rawProps: DrawerProps) => {
    const {
        open,
        onOpenChange,
        placement = 'left',
        children,
        contentClassName,
        resizable = false,
        size,
        minSize,
        maxSize,
        onResizeStart,
        onResizeEnd,
        onResize,
        className,
        style,
        qa,
        disableEscapeKeyDown,
        initialFocus,
        returnFocus,
        disableBodyScrollLock = false,
        contentOverflow = 'visible',
        disableVisuallyHiddenDismiss,
        onTransitionIn,
        onTransitionInComplete,
        onTransitionOut,
        onTransitionOutComplete,
        floatingRef,
        disablePortal,
        keepMounted = false,
        container,
        hideVeil = false,
        disableTransition = false,
        ...restProps
    } = useDefaultProps('Drawer', rawProps);
    const floatingNodeId = useFloatingNodeId();
    const disableOutsideClick = hideVeil || restProps.disableOutsideClick;

    const {refs, context} = useFloating({
        nodeId: floatingNodeId,
        open,
        onOpenChange,
    });
    const overlayRef = React.useRef(null);

    const {isMounted, status} = useFloatingTransition({
        context,
        duration: disableTransition ? 0 : DRAWER_ANIMATION_DURATION_MS,
        onTransitionIn,
        onTransitionInComplete,
        onTransitionOut,
        onTransitionOutComplete,
    });

    useInitialFocus({open, initialFocus, floatingRef: refs.floating});

    const dismiss = useDismiss(context, {
        enabled: !disableEscapeKeyDown || !disableOutsideClick,
        outsidePress: (event) => {
            if (disableOutsideClick) {
                return false;
            }

            const isOwnOutsideClick =
                (event.target as HTMLElement).closest(`.${b()}`) === overlayRef.current;

            if (!isOwnOutsideClick) {
                return false;
            }

            return true;
        },
        escapeKey: !disableEscapeKeyDown,
    });

    const role = useRole(context, {role: 'dialog'});
    const {getFloatingProps} = useInteractions([dismiss, role]);
    /*
     *  TODO: Remove casting in React 19 (https://github.com/gravity-ui/uikit/issues/2537)
     */
    const handleFloatingRef = useForkRef<HTMLDivElement>(
        refs.setFloating,
        floatingRef as React.Ref<HTMLDivElement>,
    );

    const composedStyle = React.useMemo(
        () => ({
            position: (disablePortal ? 'absolute' : 'fixed') as React.CSSProperties['position'],
            '--_--animation-duration': disableTransition
                ? '0ms'
                : `${DRAWER_ANIMATION_DURATION_MS}ms`,
            ...style,
        }),
        [disablePortal, disableTransition, style],
    );

    const portal =
        isMounted || keepMounted ? (
            <Portal container={container} disablePortal={disablePortal}>
                <FloatingOverlay
                    style={composedStyle}
                    ref={overlayRef}
                    className={b(
                        {
                            open,
                            placement,
                            'hide-veil': hideVeil,
                        },
                        className,
                    )}
                    data-qa={qa}
                    data-floating-ui-status={status}
                    lockScroll={!disableBodyScrollLock}
                >
                    <FloatingFocusManager
                        context={context}
                        disabled={!isMounted}
                        modal={isMounted}
                        initialFocus={refs.floating}
                        returnFocus={returnFocus}
                        visuallyHiddenDismiss={disableVisuallyHiddenDismiss ? false : i18n('close')}
                        restoreFocus={true}
                    >
                        <DrawerItem
                            ref={handleFloatingRef}
                            open={open}
                            placement={placement}
                            className={contentClassName}
                            contentOverflow={contentOverflow}
                            resizable={resizable}
                            size={size}
                            onResize={onResize}
                            onResizeStart={onResizeStart}
                            onResizeEnd={onResizeEnd}
                            minSize={minSize}
                            maxSize={maxSize}
                            overlayRef={overlayRef}
                            {...filterDOMProps(restProps, {labelable: true})}
                            {...getFloatingProps()}
                        >
                            {children}
                        </DrawerItem>
                    </FloatingFocusManager>
                </FloatingOverlay>
            </Portal>
        ) : null;

    return <FloatingNode id={floatingNodeId}>{portal}</FloatingNode>;
};
